parameters.jsCode:
// Construit un résumé lisible. Il est écrit en base par la fonction SQL ;
// ce nœud sert à le rendre exploitable si l'on branche plus tard un canal
// de diffusion (e-mail, Slack) sans toucher au reste du flux.
const lignes = $input.all().map(l => l.json);
const bloquees = lignes.filter(l => l.jours_attente >= 3);

const resume = lignes.map(l =>
  `${l.code.padEnd(10)} ${String(l.valeur).padStart(10)} ${l.unite || ''}  ` +
  `${l.statut.padEnd(10)} depuis ${l.jours_attente} j  (${l.saisie_par || 'inconnu'})`
).join('\n');

return [{ json: {
  total: lignes.length,
  bloquees_3j_ou_plus: bloquees.length,
  plus_ancienne_jours: lignes.length ? Math.max(...lignes.map(l => l.jours_attente)) : 0,
  resume,
  // Rappel du lien avec la règle centrale : tant qu'une valeur n'est pas
  // validée, l'IA ne la voit pas. Une file d'attente qui grossit, c'est
  // une analyse qui s'appauvrit.
  consequence: 'Ces valeurs ne sont pas transmises au modèle IA.',
}}];
